import axios, { AxiosResponse } from 'axios';

import { inversifyContainer } from '../inversify/container';
import { userModel } from '../models/user';
import { environment } from './environment';
import { device } from './device';
import { IGameConfigResponse } from '../types';
import { queryStringParams } from './query-string';

export class GameConfigProvider {
    private cachedResponse: IGameConfigResponse | undefined;

    public async fetch(ignoreCache: boolean = false): Promise<IGameConfigResponse | undefined> {
        if (this.cachedResponse && !ignoreCache) { return this.cachedResponse; }

        let gameConfigResponse: AxiosResponse<IGameConfigResponse, unknown> | undefined;
        try {
            const isDemo = queryStringParams.isUnAuthDemoMode;
            const launcherUrl = isDemo ? inversifyContainer.endPoints.demoGameLaunchers : inversifyContainer.endPoints.gameLaunchers;
            const url = inversifyContainer.endPoints.urls[environment].api + launcherUrl;
            const auth = window.btoa(`${userModel.userId}:${userModel.crossCheck}`);
            gameConfigResponse = await axios.get(url, {
                withCredentials: true,
                headers: {
                    Authorization: `Basic ${auth}`,
                    'X-Tombola-Deviceidentifier': device.deviceID,
                    'X-Tombola-Devicetype': device.type.value
                }
            });
            this.cachedResponse = gameConfigResponse?.data;
            return this.cachedResponse;

        } catch (error: any) {
            // report any errors loading the game launchers but allow the game to continue
            if (error.response) {
                console.error(error.response);
            } else if (error.request) {
                console.error(error.request);
            }
            console.error(error.message);
        }
    }
}